POSITIVE = ('满意', '推荐', '很好')
NEGATIVE = ('失望', '慢', '差')


def sentiment(text):
    if any(word in text for word in NEGATIVE):
        return 'negative'
    if any(word in text for word in POSITIVE):
        return 'positive'
    return 'negative'

print(sentiment('这家店服务很好，强烈推荐'))

